export const challenges=[{"id": "ch-001", "title": "تبلیغ سنگ لاکچری", "text": "مجری یک سنگ یا شیء ساده انتخاب می‌کند. ۲۰ ثانیه وقت داری آن را مثل یک محصول فوق‌لوکس و غیرقابل‌جایگزین بفروشی.", "type": "performance"}, {"id": "ch-002", "title": "مستند حیات‌وحش", "text": "یکی از بازیکن‌ها را انتخاب کن و ۳۰ ثانیه مثل مستند حیات‌وحش، رفتار کاملاً عادی او را با جدیت گزارش کن.", "type": "performance"}, {"id": "ch-003", "title": "اسکار برای یک جمله", "text": "مجری یک جمله معمولی مثل «آب می‌خوری؟» می‌گوید. همان جمله را مثل سکانس پایانی یک فیلم اسکاری اجرا کن.", "type": "performance"}, {"id": "ch-004", "title": "دادگاه جوراب گمشده", "text": "۲۰ ثانیه از یک جوراب متهم به ناپدیدشدن جفتش دفاع کن؛ انگار وکیل پرونده قرن هستی.", "type": "performance"}, {"id": "ch-005", "title": "بحث با درخت", "text": "۳۰ ثانیه با یک درخت یا نیمکت بحث کن؛ موضوع دعوا این است که پنج سال است پولت را پس نداده.", "type": "performance"}, {"id": "ch-006", "title": "تئوری توطئه فوری", "text": "مجری سه کلمه بی‌ربط می‌دهد. در ۳۰ ثانیه یک تئوری توطئه خنده‌دار بساز که هر سه را به هم وصل کند.", "type": "performance"}, {"id": "ch-007", "title": "اخبار آخرالزمانی", "text": "یک اتفاق کاملاً عادی اطراف را مثل خبر فوری پایان دنیا گزارش کن.", "type": "performance"}, {"id": "ch-008", "title": "محصول افتضاح", "text": "یک محصول خیالی واقعاً بد اختراع کن و ۲۰ ثانیه طوری تبلیغش کن که بقیه وسوسه شوند بخرند.", "type": "performance"}, {"id": "ch-009", "title": "نسخه ۸۰ ساله", "text": "یکی از بازیکن‌ها را انتخاب کن و ۲۰ ثانیه نقش نسخه ۸۰ ساله او را بازی کن؛ محترمانه و بدون مسخره‌کردن ظاهر.", "type": "performance"}, {"id": "ch-010", "title": "خاکسپاری چیپس", "text": "برای یک خوراکی شکسته یا شیء بی‌اهمیت، یک مراسم خداحافظی فوق‌احساسی ۲۰ ثانیه‌ای اجرا کن.", "type": "performance"}, {"id": "ch-011", "title": "مصاحبه با بطری", "text": "یک بطری یا شیء دم‌دستی مهمان برنامه گفت‌وگومحور توست. هم مجری باش، هم مهمان.", "type": "performance"}, {"id": "ch-012", "title": "سوپراستار شدن", "text": "طوری وارد جمع شو که انگار مشهورترین آدم دنیا هستی و همه منتظر ورودت بوده‌اند.", "type": "performance"}, {"id": "ch-013", "title": "دوبله اشتباه", "text": "یک نفر ۱۵ ثانیه بی‌صدا حرکت کند؛ تو همزمان برایش یک دیالوگ کاملاً نامربوط دوبله کن.", "type": "performance"}, {"id": "ch-014", "title": "آشپزی ناممکن", "text": "مجری سه چیز غیرخوراکی می‌گوید. مثل سرآشپز حرفه‌ای دستور پخت غذایی با آن‌ها را توضیح بده.", "type": "performance"}, {"id": "ch-015", "title": "فروش هوای پارک", "text": "۳۰ ثانیه فرصت داری «هوای همین‌جا» را بسته‌بندی و به جمع بفروشی.", "type": "performance"}, {"id": "ch-016", "title": "جلسه اضطراری", "text": "یک موضوع بی‌اهمیت مثل تمام‌شدن دستمال کاغذی را موضوع جلسه فوق‌محرمانه بحران ملی قرار بده.", "type": "performance"}, {"id": "ch-017", "title": "فیلم در پنج کلمه", "text": "یک فیلم معروف را فقط با پنج کلمه توضیح بده تا بقیه حدس بزنند.", "type": "performance"}, {"id": "ch-018", "title": "پانتومیم شغل عجیب", "text": "مجری یک شغل عجیب ترکیبی مثل «دندانپزشک فضایی» می‌سازد؛ بدون حرف اجرا کن.", "type": "performance"}, {"id": "ch-019", "title": "سه احساس", "text": "یک جمله ثابت را سه بار با احساس‌های کاملاً متفاوت: عاشقانه، وحشت‌زده و عصبانی اجرا کن.", "type": "performance"}, {"id": "ch-020", "title": "آهنگ بدون کلمه", "text": "یک آهنگ معروف را فقط با «لا لا» یا زمزمه اجرا کن تا جمع حدس بزند.", "type": "performance"}, {"id": "ch-021", "title": "کنفرانس خبری شکست", "text": "نقش مربی تیمی را بازی کن که در مسابقه‌ای کاملاً مسخره مثل «مسابقه خوابیدن» باخته است.", "type": "performance"}, {"id": "ch-022", "title": "راهنمای استفاده از انسان", "text": "یکی از بازیکن‌ها را انتخاب کن و مثل دفترچه راهنما، سه دستور بامزه و محترمانه برای کارکردن با او بگو.", "type": "performance"}, {"id": "ch-023", "title": "اختراع بی‌مصرف", "text": "یک اختراع کاملاً بی‌مصرف معرفی کن و توضیح بده چرا بشریت بدون آن نابود می‌شود.", "type": "performance"}, {"id": "ch-024", "title": "مترجم حیوانات", "text": "مجری یک حیوان می‌گوید. اول صدایش را اجرا کن و بعد ترجمه کن که دقیقاً چه گفته.", "type": "performance"}, {"id": "ch-025", "title": "تریلر زندگی عادی", "text": "کاری عادی مثل رفتن برای خرید نان را مثل تریلر یک فیلم اکشن بزرگ تعریف کن.", "type": "performance"}, {"id": "ch-026", "title": "رستوران فاجعه", "text": "منوی رستورانی بساز که هیچ‌کس عاقلانه نباید از آن غذا سفارش بدهد؛ سه غذا معرفی کن.", "type": "performance"}, {"id": "ch-027", "title": "پیام صوتی تاریخی", "text": "فرض کن یک شخصیت تاریخی برای گروه ویس فرستاده؛ ۲۰ ثانیه آن ویس را بازی کن، بدون توهین یا موضوع سیاسی روز.", "type": "performance"}, {"id": "ch-028", "title": "پشتیبانی مشتریان", "text": "یک نفر مشتری عصبانیِ محصول خیالی است؛ تو باید به‌عنوان پشتیبانی با جدیت مشکل عجیبش را حل کنی.", "type": "performance"}, {"id": "ch-029", "title": "تور لیدر عجیب", "text": "یک نقطه کاملاً معمولی نزدیکتان را مثل مشهورترین جاذبه گردشگری جهان معرفی کن.", "type": "performance"}, {"id": "ch-030", "title": "سوپرقدرت بدردنخور", "text": "یک ابرقدرت تقریباً بی‌فایده برای خودت انتخاب کن و نشان بده چطور دنیا را با آن نجات می‌دهی.", "type": "performance"}, {"id": "ch-031", "title": "فیلم صامت", "text": "۲۰ ثانیه داستان «جا گذاشتن کلید» را بدون هیچ کلمه‌ای، با شروع و پایان مشخص بازی کن.", "type": "performance"}, {"id": "ch-032", "title": "شعر تبلیغاتی", "text": "برای یک شیء انتخابی مجری، همان لحظه یک شعر تبلیغاتی دو خطی بساز.", "type": "performance"}, {"id": "ch-033", "title": "مربی انگیزشی عجیب", "text": "۳۰ ثانیه جمع را برای انجام کاری فوق‌العاده ساده مثل بلندشدن از صندلی انگیزه بده.", "type": "performance"}, {"id": "ch-034", "title": "رادیوی نیمه‌شب", "text": "مثل گوینده رادیوی نیمه‌شب، درباره یک موضوع خنده‌دار با صدایی بیش‌ازحد جدی حرف بزن.", "type": "performance"}, {"id": "ch-035", "title": "بازجویی از شیء", "text": "یک شیء را به جرم خیالی بازجویی کن و خودت جواب‌هایش را هم بده.", "type": "performance"}, {"id": "ch-036", "title": "آپدیت نرم‌افزاری خودت", "text": "نسخه جدید خودت را معرفی کن: سه قابلیت جدید و یک باگ خنده‌دار.", "type": "performance"}, {"id": "ch-037", "title": "پیش‌بینی هوا عجیب", "text": "هوای فردا را پیش‌بینی کن، اما هر پدیده جوی باید یک اثر مسخره روی زندگی مردم داشته باشد.", "type": "performance"}, {"id": "ch-038", "title": "موزه آینده", "text": "یک شیء امروزی را طوری معرفی کن که انگار در سال ۲۵۰۰ داخل موزه پیدا شده.", "type": "performance"}, {"id": "ch-039", "title": "قهرمان کار کوچک", "text": "یک کار خیلی کوچک مثل بازکردن در بطری را مثل بزرگ‌ترین مأموریت قهرمانانه زندگی‌ات اجرا کن.", "type": "performance"}, {"id": "ch-040", "title": "صدای ذهن", "text": "یکی از بازیکن‌ها یک کار عادی انجام دهد؛ تو صدای ذهن خیالی و بامزه‌اش باش.", "type": "performance"}, {"id": "ch-041", "title": "دیکشنری جدید", "text": "سه کلمه ساختگی اختراع کن و معنی هرکدام را با اعتمادبه‌نفس توضیح بده.", "type": "performance"}, {"id": "ch-042", "title": "جلسه استخدام", "text": "برای شغل خیالی «مسئول کنترل ابرها» مصاحبه کاری بده و ثابت کن بهترین گزینه‌ای.", "type": "performance"}, {"id": "ch-043", "title": "گزارش ورزشی", "text": "یک کار معمولی یکی از بچه‌ها را مثل فینال جام جهانی با هیجان گزارش کن.", "type": "performance"}, {"id": "ch-044", "title": "جادوگر کم‌بودجه", "text": "یک شعبده کاملاً ساختگی را اجرا کن و وقتی جواب نداد، با اعتمادبه‌نفس توضیح علمی بده.", "type": "performance"}, {"id": "ch-045", "title": "سخنرانی پذیرش جایزه", "text": "برای بردن جایزه‌ای عجیب مثل «بهترین نشستن سال» یک سخنرانی تشکر احساسی اجرا کن.", "type": "performance"}, {"id": "ch-046", "title": "خلاصه سریال خیالی", "text": "داستان یک سریال خیالی ۱۰۰ قسمتی را در ۳۰ ثانیه تعریف کن.", "type": "performance"}, {"id": "ch-047", "title": "ربات تازه‌کار", "text": "۲۰ ثانیه نقش رباتی را بازی کن که تازه احساسات انسانی را یاد گرفته و همه‌چیز را اشتباه می‌فهمد.", "type": "performance"}, {"id": "ch-048", "title": "مناظره اشیا", "text": "دو شیء اطراف را انتخاب کن و به‌جای هر دو بحث کن که کدام برای بشریت مهم‌تر است.", "type": "performance"}, {"id": "ch-049", "title": "تبلیغ ضدتبلیغ", "text": "یک چیز خوب را طوری تبلیغ کن که ناخواسته هر جمله‌ات آن را بدتر جلوه دهد.", "type": "performance"}, {"id": "ch-050", "title": "کارشناس بی‌ربط", "text": "مجری یک موضوع ساده می‌گوید؛ با اصطلاحات کاملاً ساختگی مثل یک کارشناس فوق‌تخصصی توضیحش بده.", "type": "performance"}, {"id": "ch-051", "title": "آژانس مسافرتی", "text": "برای سفر تفریحی به یک جای نامناسب مثل داخل یخچال، تور لوکس معرفی کن.", "type": "performance"}, {"id": "ch-052", "title": "صدای سه شخصیت", "text": "یک جمله را با صدای سه شخصیت خیالی کاملاً متفاوت اجرا کن.", "type": "performance"}, {"id": "ch-053", "title": "کلاس آموزشی بدیهیات", "text": "در ۲۰ ثانیه یک آموزش فوق‌حرفه‌ای برای کاری بدیهی مثل پلک‌زدن ارائه بده.", "type": "performance"}, {"id": "ch-054", "title": "پایان غیرمنتظره", "text": "داستانی ۳۰ ثانیه‌ای تعریف کن که عادی شروع شود و با جمله «ولی مشکل این نبود...» مسیرش عوض شود.", "type": "performance"}, {"id": "ch-055", "title": "برند شخصی عجیب", "text": "برای خودت یک برند خیالی بساز: اسم، شعار و محصول اصلی‌ات را در ۲۰ ثانیه معرفی کن.", "type": "performance"}, {"id": "ch-056", "title": "تلفن به گذشته", "text": "فرض کن فقط ۲۰ ثانیه می‌توانی به انسان‌های ۵۰۰ سال قبل زنگ بزنی؛ یک چیز امروزی را برایشان توضیح بده.", "type": "performance"}, {"id": "ch-057", "title": "مهمانی فضایی", "text": "نقش موجود فضایی را بازی کن که اولین بار به یک دورهمی انسانی آمده و قوانینش را اشتباه فهمیده.", "type": "performance"}, {"id": "ch-058", "title": "مترجم رسمی بچه‌گانه", "text": "یک جمله رسمی و جدی را طوری ترجمه کن که یک بچه پنج‌ساله بفهمد، ولی بامزه بماند.", "type": "performance"}, {"id": "ch-059", "title": "تبلیغ فیلم جمع", "text": "برای همین دورهمی یک تریلر سینمایی ۲۰ ثانیه‌ای بساز و حداقل دو نفر از جمع را در داستان جا بده.", "type": "performance"}, {"id": "ch-060", "title": "فینال بزرگ", "text": "مجری یک شیء ساده می‌دهد؛ ۳۰ ثانیه فرصت داری با ترکیب بازیگری، تبلیغ و داستان، جمع را قانع کنی این مهم‌ترین شیء جهان است.", "type": "performance"}];
