for(const q of v23MoreQuestions){ if(!bank[q.category]) bank[q.category]={}; if(!bank[q.category][q.value]) bank[q.category][q.value]=[]; bank[q.category][q.value].push(q); }
export const categories=["هنر و معماری","علم و طبیعت","ریاضی و منطق","ورزش","فیلم و سریال","موسیقی","تاریخ","جغرافیا","غذا و خوراکی","حیوانات","فناوری و اینترنت","ایران و فرهنگ","اطلاعات عمومی",...v23ExtraCategories,"چالش"];

