// V23 difficulty rebalance for the player-facing categories.
// We intentionally stop using the old specialist-heavy 600 pool. Higher values now select from broadly accessible questions.
function v23RebalanceCategory(cleanName){
  const source=bank[legacyCategoryAliases[cleanName]];
  if(!source) return;
  const unique=(arr)=>{const seen=new Set(); return (arr||[]).filter(q=>{const k=q.id||q.text; if(seen.has(k)) return false; seen.add(k); return true;});};
  const pool={}; for(const v of values) pool[v]=unique(source[v]);
  const used=new Set();
  const take=(vals,n)=>{const out=[]; for(const v of vals){for(const q of pool[v]){const k=q.id||q.text; if(used.has(k)) continue; used.add(k); out.push(q); if(out.length>=n) return out;}} return out;};
  bank[cleanName]={
    200:take([200],10),
    300:take([300,200],10),
    400:take([400,300,200],10),
    500:take([400,500,300],10),
    600:take([500,400,600,300],10)
  };
}

["هنر و معماری","علم و طبیعت","ریاضی و منطق","ورزش","فیلم و سریال","موسیقی","اطلاعات عمومی"].forEach(v23RebalanceCategory);

// Rebuild V23-only categories after the second content pass.
for(const c of v23Categories){
  bank[c]={200:[],300:[],400:[],500:[],600:[]};
}
for(const q of v23Questions){ if(bank[q.category]) bank[q.category][q.value].push(q); }
for(const q of v23MoreQuestions){ if(bank[q.category]) bank[q.category][q.value].push(q); }
// Final V23 bank hygiene: remove duplicate IDs/texts inside each visible category/tier.
for(const category of categories){
  if(!bank[category]) continue;
  const __seenText=new Set();
  for(const value of values){
    const qs=bank[category]?.[value]||[];
    bank[category][value]=qs.filter(q=>{const key=q.text.trim(); if(__seenText.has(key)) return false; __seenText.add(key); return true;});
  }
}


